window.DIGEST.following.push(...[{"id": "2112996774906638640", "url": "https://x.com/beffjezos/status/2112996774906638640", "text": "One of my most candid / human conversations on air.\n\nTalked about my journey, theoretical physics, from quantum to thermo computing, the principles of e/acc, human psychology, scaling a movement, the need for an intellectual revolution, Kardashev Research, & more", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 170, "rts": 14, "replies": 18, "views": 10713, "ts": 1792612663, "media": [], "quote": {"id": "2112996186106065199", "url": "https://x.com/ashebytes/status/2112996186106065199", "text": "on the physics of intelligence & being human\n\nin conversation with @beffjezos\n\n04:30 the masks we learn to wear\n21:43 thermodynamic computing\n32:52 the origins of e/acc\n56:06 forgiveness & boundaries\n1:01:41 keeping an open heart", "name": "ashe", "handle": "ashebytes", "avatar": "https://pbs.twimg.com/profile_images/2068592289761636352/kMaWy2mb_200x200.jpg", "likes": 252, "rts": 29, "replies": 26, "views": 33335, "ts": 1792612522, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112944711535353858/vid/avc1/1280x720/wqNJP6qHdiu_jKBL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112944711535353858/vid/avc1/1920x1080/Co7WeAy5ocu6w-vc.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVMyZcEbsAAJwI6.jpg", "dur": 5184}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 5.9, "thread": [], "tier": "worth"}, {"id": "2112914305058582844", "url": "https://x.com/SakanaAILabs/status/2112914305058582844", "text": "QD-Rec: Open-Ended Evolution of Recommendations via Quality–Diversity\n\nBlog: http://pub.sakana.ai/qd-rec\nGitHub: http://github.com/SakanaAI/QD-Rec\narXiv: https://arxiv.org/abs/2610.23470\n\nOpen-ended search has been used to discover algorithms, generate scientific ideas, and develop self-improving agents. With QD-Rec, we explore how it can support a different kind of task: helping people make decisions.\n\nWhich company should an acquirer buy? Which customers might benefit from a product? Which papers should a researcher read? In each case, the task is to choose among existing options, not generate new ones. At first glance, a finite, predefined candidate pool seems to leave little room for open-ended exploration.\n\nHowever, a fixed set of options does not imply a fixed set of reasons for choosing them. The same company might be worth considering for its technology or its potential to open up a new market. The search over these reasons remains open-ended even when the options themselves are fixed.\n\nQD-Rec searches over both what to recommend and why. Instead of aiming for a single best answer, it builds a diverse collection of recommendations, each pairing a candidate with a natural-language hypothesis explaining why it fits a particular decision maker’s goals, interests, and background.\n\nThe system combines three components. A contextual bandit learns which items to investigate next, balancing promising candidates with less-explored ones. An LLM generates hypotheses by adapting or combining the earlier recommendations. An archive retains new recommendations when they offer a novel reason, or replaces a similar recommendation when the new one is judged better.\n\nWe evaluate QD-Rec on acquisition target discovery, customer targeting, and paper recommendation. Compared with variants that remove evolutionary hypothesis generation or contextual bandits, QD-Rec achieves the highest mean LLM-rated quality in most settings and usually builds the largest archive. We also found examples where earlier recommendations with a low quality became stepping stones for later discoveries.\n\nThese experiments are a starting point. Practical applications will require richer, up-to-date information and expert human feedback to assess whether the proposed QD-Rec holds up beyond evaluation by an LLM judge.\n\nWe are releasing the code for QD-Rec so that researchers and practitioners can explore open-ended recommendation with their own decision-making tasks.", "name": "Sakana AI", "handle": "SakanaAILabs", "avatar": "https://pbs.twimg.com/profile_images/1885939209388929024/dtnrOdGp_200x200.jpg", "likes": 181, "rts": 28, "replies": 8, "views": 12823, "ts": 1792593001, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVG4dl0a8AAlBJZ.mp4", "hd": "https://video.twimg.com/tweet_video/HVG4dl0a8AAlBJZ.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVG4dl0a8AAlBJZ.jpg", "dur": 0}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.84, "thread": [], "tier": "worth"}, {"id": "2112922749320548735", "url": "https://x.com/MidcenturyAI/status/2112922749320548735", "text": "Introducing Akari: a frontier learned rendering model for robotics simulation.\n\nAkari generates photorealistic rendering for any physics engine to close the sim-to-real gap.\n\nTrained in-house, it is the fastest and highest-fidelity learned renderer in any sim platform: 0.046 LPIPS at 0.5s/frame, consistent across 1K+ frames.", "name": "Midcentury", "handle": "MidcenturyAI", "avatar": "https://pbs.twimg.com/profile_images/2112263768176467968/6cDFN3jG_200x200.jpg", "likes": 196, "rts": 13, "replies": 17, "views": 14721, "ts": 1792595014, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112922689467822080/vid/avc1/1280x720/yEM6MzbegciuI88N.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112922689467822080/vid/avc1/3840x2160/drLbBWBkk5gsijnb.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112922689467822080/img/bkT7bwwHFyXujzZp.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.83, "thread": [], "tier": "worth"}, {"id": "2112899505708265794", "url": "https://x.com/LuminaBench/status/2112899505708265794", "text": "First impressions of Gemini 4 Carbon from arena testing:\n\nIt's extremely strong at 3D tasks / games, a massive improvement is that it's no longer lazy, it understands what you want takes its time and does it, instead of just trying to be quick like Argon\n\nOne negative is Frontend design / taste, it's still average and lacks what Anthropic models have", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 228, "rts": 9, "replies": 15, "views": 10913, "ts": 1792589472, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.82, "thread": [], "tier": "worth"}, {"id": "2112941047072559257", "url": "https://x.com/MTSlive/status/2112941047072559257", "text": "SITUATION BREWING: Anthropic AI is preparing to file its S-1 investor prospectus as soon as this Friday, per a report from Yahoo Finance.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 217, "rts": 8, "replies": 5, "views": 12687, "ts": 1792599376, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.82, "thread": [], "tier": "worth"}, {"id": "2112998585847681378", "url": "https://x.com/KobeissiLetter/status/2112998585847681378", "text": "BREAKING: Meta stock, $META, surges +5% after reporting stronger than expected Q3 2026 earnings.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 2478, "rts": 167, "replies": 101, "views": 221703, "ts": 1792613095, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLhA7qW4AAmN6y.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 5.81, "thread": [], "tier": "worth"}, {"id": "2112853528712560868", "url": "https://x.com/Andy_AJT/status/2112853528712560868", "text": "DevDay is coming to London 🇬🇧\n\nWe're throwing a HUGE hackathon, 1st November with amazing prizes + special guests + SWAG! \n\nChatGPT Pro Subscriptions + Codex Credits + OpenAI API Credits + Tickets to DDE London 🟣\n\nThis is NOT to be missed - the team have been planning for months and this is going be epic!\n\nlast few Codex London events had 1000+ registrations so sign up fast\n\nMore info coming soon... \n\nSign up now 👇", "name": "Andy T", "handle": "Andy_AJT", "avatar": "https://pbs.twimg.com/profile_images/2080234399493189632/DSzvb0lY_200x200.jpg", "likes": 208, "rts": 18, "replies": 26, "views": 16848, "ts": 1792578510, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112849482907856896/vid/avc1/720x720/rgYAmnR-qqxjgCzf.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112849482907856896/vid/avc1/2160x2160/FtxweC-CjjeBMiP1.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112849482907856896/img/7RxjDRCFPLh5_20K.jpg", "dur": 6}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.8, "thread": [], "tier": "worth"}, {"id": "2112901415937200432", "url": "https://x.com/MTSlive/status/2112901415937200432", "text": "SITUATION DETECTED: OpenAI and Google Cloud are partnering to bring OpenAI’s models and Codex to Google Cloud’s Model Garden and Antigravity.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 236, "rts": 4, "replies": 6, "views": 14592, "ts": 1792589928, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.79, "thread": [], "tier": "worth"}, {"id": "2112974373883875677", "url": "https://x.com/willcb/status/2112974373883875677", "text": "applied research at prime intellect is both a client-facing team and a fundamental research team. continual learning is our north star. we view this dual approach as necessary in order to study the core challenges faced by models which self-improve in production. the real world is big and messy.\n\nwe spend part of our our time working with customers to train SOTA models for specialized domains, and we automate and productize our work as we go. we also do open-ended research on novel methods for self-improvement and long-horizon memory, and we get to experiment with data that no other lab gets to see. \n\ntoday, the most readily-deployable form of continual learning is converting \"exhaust\" (agent traces, logs, feedback) into robust environments and tasks for continual RL. but this is not the final form. there are major open challenges around knowledge acquisition, harness-weight tradeoffs, user modeling, dynamic underspecified preferences, updating and planning across timescales, selective forgetting, data efficiency, learning from golden answers, and company-scale simulation. this is the roadmap, roughly speaking. \n\nsome of these may require changes to architecture, or parameter-efficient methods, or fundamentally new algorithms. we have our hypotheses and early evidence, but everything is on the table. the world is our oyster. \n\nwe are betting on a radically different future of what ai deployment will look like, and we can see the path more clearly every day. it is a world where agents learn like humans do, with billions of individual models compounding their learnings from the real world continuously.\n\nwe're hiring incredibly ambitious researchers in SF, NY, and London. come join us.", "name": "will brown", "handle": "willcb", "avatar": "https://pbs.twimg.com/profile_images/1851112754439974912/CeTvIgQ4_200x200.jpg", "likes": 169, "rts": 7, "replies": 10, "views": 15084, "ts": 1792607322, "media": [], "quote": null, "reply_to": "2112968443225928071", "cat": "AI Tools & Agents", "score": 5.79, "thread": [{"id": "2112968443225928071", "url": "https://x.com/willcb/status/2112968443225928071", "text": "over the past few months we've been rapidly scaling our partnerships with leading companies across a bunch of incredibly exciting domains\n\nwe collaborate with their in-house experts to deploy continual learning loops in prod\n\nhiring for many new roles :)\n\nhttps://www.primeintellect.ai/careers", "name": "will brown", "handle": "willcb", "avatar": "https://pbs.twimg.com/profile_images/1851112754439974912/CeTvIgQ4_200x200.jpg", "likes": 197, "rts": 7, "replies": 9, "views": 9736, "ts": 1792605908, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLDwkkXgAA55bV.jpg?name=orig"}], "quote": null, "reply_to": null}], "tier": "worth"}, {"id": "2112989926195429615", "url": "https://x.com/LuminaBench/status/2112989926195429615", "text": "When Fable 5.5 drops it might be over\n\nOpenAI just can't catch a break", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 153, "rts": 4, "replies": 14, "views": 4107, "ts": 1792611030, "media": [], "quote": {"id": "2112984783068561883", "url": "https://x.com/LuminaBench/status/2112984783068561883", "text": "Anthropic are launching Claude Duet\n\nThis looks like their version of Grok bot / OpenAI's dots from what I can see", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 292, "rts": 5, "replies": 18, "views": 10078, "ts": 1792609804, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLTWNyW8AIIsPb.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.78, "thread": [], "tier": "worth"}, {"id": "2112898614741655773", "url": "https://x.com/Yoshua_Bengio/status/2112898614741655773", "text": "Misuse by malicious actors is a risk with any powerful technology; but in the case of AI, the consequences could be catastrophic.\n\nVery interesting analysis by @StephenLCasper on how AI developers' decisions can influence cyber, bio, and chemical terrorism risks.", "name": "Yoshua Bengio", "handle": "Yoshua_Bengio", "avatar": "https://pbs.twimg.com/profile_images/2033915590566428672/NVNxLW6g_200x200.jpg", "likes": 139, "rts": 33, "replies": 11, "views": 8427, "ts": 1792589260, "media": [], "quote": {"id": "2112555723813003647", "url": "https://x.com/StephenLCasper/status/2112555723813003647", "text": "🚨New paper (possibly the most important one I have written yet).\n\nWe think that as early as 2027 or 2028, there might be a major AI-enabled terrorism event. We conducted a pre-mortem, made 9 falsifiable predictions, and wrote 2 concrete scenarios.\n\nLed by @KamacheeMax.", "name": "Cas (Stephen Casper)", "handle": "StephenLCasper", "avatar": "https://pbs.twimg.com/profile_images/2043825823753318400/DLZ3Rs-U_200x200.jpg", "likes": 635, "rts": 130, "replies": 22, "views": 117832, "ts": 1792507508, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFJlG5W0AAbc2T.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFJpISX0AAEC0T.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 5.78, "thread": [], "tier": "worth"}, {"id": "2112907406179176690", "url": "https://x.com/elder_plinius/status/2112907406179176690", "text": "we really got PET TERMINATORS before GTA 6 🤪", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 194, "rts": 7, "replies": 15, "views": 14509, "ts": 1792591356, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKOFjmagAAbhsI.jpg?name=orig"}], "quote": {"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20511, "rts": 2766, "replies": 1427, "views": 4243630, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.77, "thread": [], "tier": "worth"}, {"id": "2112783799209927128", "url": "https://x.com/adcock_brett/status/2112783799209927128", "text": "Let Hark run your life for you", "name": "Brett Adcock", "handle": "adcock_brett", "avatar": "https://pbs.twimg.com/profile_images/1975050867842908160/H-pYm78t_200x200.jpg", "likes": 231, "rts": 8, "replies": 48, "views": 27699, "ts": 1792561886, "media": [], "quote": {"id": "2112781288788906086", "url": "https://x.com/markjenney/status/2112781288788906086", "text": "I'm running my entire life on Hark now @hark_labs . My ChatGPT and Claude usage has decreased 99% since I started using Hark two weeks ago. This product has positively impacted my life more than any other product I have ever used.", "name": "Mark Jenney", "handle": "markjenney", "avatar": "https://pbs.twimg.com/profile_images/1447733203716902915/LHIXjIIR_200x200.jpg", "likes": 114, "rts": 3, "replies": 20, "views": 35413, "ts": 1792561287, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.75, "thread": [], "tier": "worth"}, {"id": "2112992489481101725", "url": "https://x.com/Dr_Singularity/status/2112992489481101725", "text": "a lot is happening this week...\n\nAnthropic launches Claude Duet, a personal AI assistant that keeps working after you close the app. \n\nPowered by Opus 5.5, it runs on its own cloud computer and takes instructions through text or voice messages.\n\nIt can prepare morning briefings from your email and calendar, draft replies, follow up on quiet threads, research companies before meetings, check unpaid Stripe invoices, and create slide decks, financial models and dashboards. \n\nIt also uses a cloud browser for websites without connectors and carries over your existing Claude memory, skills and connected apps.\n\nIt even supports approved purchases through Link and Shop Pay, while asking before sending messages, making payments, signing documents or deleting anything.", "name": "Dr Singularity", "handle": "Dr_Singularity", "avatar": "https://pbs.twimg.com/profile_images/1607111366397120514/j4XzXC27_200x200.jpg", "likes": 131, "rts": 7, "replies": 13, "views": 6898, "ts": 1792611641, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLbRhcXcAAt63F.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.75, "thread": [], "tier": "worth"}, {"id": "2112984466365071540", "url": "https://x.com/shiraeis/status/2112984466365071540", "text": "Parents don’t need yet another app charting their baby’s sleep. They need the baby to be asleep.\n\nNight Nanny does the trial & error for you, & keeps learning what works to calm your baby.\n\nNot shown: safety, a separate camera + sensor system that alerts you to crib risks like a covered face or unsafe sleeping positions.\n\nDemoing live at an event for families in SF this Sunday October 25! DM for details :)", "name": "shira", "handle": "shiraeis", "avatar": "https://pbs.twimg.com/profile_images/1874894815202082816/3CDH0mDO_200x200.jpg", "likes": 110, "rts": 3, "replies": 31, "views": 8625, "ts": 1792609728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112984051992985600/vid/avc1/720x1280/22Zr6nnQuzU25ymz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112984051992985600/vid/avc1/1080x1920/8fsa3fvQBDhTL8Md.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112984051992985600/img/XoNGIcxmnaqyNFww.jpg", "dur": 150}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.74, "thread": [], "tier": "worth"}, {"id": "2112918063641194762", "url": "https://x.com/NVIDIARTXSpark/status/2112918063641194762", "text": "Local AI news from #NVIDIAGTC Berlin:\n\n🟢 @UnderdogAI local agent available on RTX Spark\n🟢 Lots of DGX Spark updates\n🟢 DGX Station: New integrations + @Windows systems coming in December\n🟢 New open models + faster inference support\n\nRead the blog: https://blogs.nvidia.com/blog/local-ai-gtc-rtx-dgx-spark-station-sync", "name": "NVIDIA RTX Spark", "handle": "NVIDIARTXSpark", "avatar": "https://pbs.twimg.com/profile_images/2061303426479431680/BDJQPK6Q_200x200.jpg", "likes": 140, "rts": 21, "replies": 8, "views": 9048, "ts": 1792593897, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKXx4lWUAAEQO-.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.73, "thread": [], "tier": "worth"}, {"id": "2113124084410425362", "url": "https://x.com/ArtificialAnlys/status/2113124084410425362", "text": "DeepSeek Search debuts on the Artificial Analysis Search Index at 69, 17th of 27 search products, at the lowest price of any paid Search API on the board\n\n@deepseek_ai launched its Search API on 17 October. We benchmarked it in our Stirrup agent harness, where GPT-5.6 Luna (medium) calls DeepSeek Search as its web_search tool to complete a combination of tasks from BrowseComp, DeepSearchQA and AA-Omniscience.\n\nAt $0.75 per 1k searches, DeepSeek Search costs less per search than any other paid Search API we benchmark, below Octen, Parallel (turbo) and Parallel (fast) at $1. At about $0.032 per task, it is the 5th cheapest of 27 products, cheaper than 20 of the other 25 Search APIs (median $0.066) and level with Nimble (lite). TinyFish, Octen, Parallel (turbo) and Parallel (fast) cost less.\n\nKey benchmarking results for DeepSeek Search:\n\n➤ Artificial Analysis Search Index: DeepSeek Search scores 69, a 36-point lift over the same model with no search (33). It sits between TinyFish at 71 and Linkup (standard) at 68\n\n➤ AA-Omniscience is DeepSeek Search's strongest benchmark: it scores 70% accuracy on our proprietary factual answer benchmark. This ranks 10th of 27, 3 points behind the joint leaders, Exa (auto, dynamic highlights) and Firecrawl (73%). BrowseComp, which needs multi-hop reasoning across several searches, is its weakest benchmark: at 63% it ranks 25th of 27, well behind the Perplexity variants and Octen (85% to 87%)\n\n➤ Large search results: each search returns about 7k tokens, near the top of the board's range. Each result carries about 1.8k characters of passages from the page. This raises model cost: at about $0.023 per task, DeepSeek's model cost is the 2nd highest on the board, behind Linkup (flash, alpha) at $0.039\n\n➤ 128-character query limit: DeepSeek rejects queries longer than 128 characters. 6% of the agent's searches hit this limit, and for 87% of these, the model's first shorter rewrite worked\n\nKey details:\n\n➤ Setup: GPT-5.6 Luna (medium) in Stirrup, DeepSeek Search API with need_content=false (page passages, no full page content) and 10 results per search\n\n➤ Pricing: $0.75 per 1k successful searches. DeepSeek does not bill empty results\n\n➤ Rate limit: 5 searches per second per account", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 80, "rts": 3, "replies": 12, "views": 9422, "ts": 1792643016, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVNS1FpaIAAsGtx.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.73, "thread": [], "tier": "worth"}, {"id": "2112818839528321479", "url": "https://x.com/lightpanda_io/status/2112818839528321479", "text": "We put Jev inside the Lightpanda binary and built judge() on top of it. @typesafeai \n\nNo more sending a whole page to an LLM just to find out it's a cookie banner.\n\n> Blocked pages, CAPTCHAs, cookie walls, logins, paywalls, error pages, empty searches and pages still loading can all return an HTTP 200\n> judge() asks a set of predefined questions and tells you if the page has real content, and what kind: article, listing, product or docs\n> One call, ~0.2s\n\nIn the video:\n> 30 sites, ~14s total\n> Lightpanda backs off when rate-limited, accepts cookie walls, and keeps or skips each page", "name": "Lightpanda", "handle": "lightpanda_io", "avatar": "https://pbs.twimg.com/profile_images/1772190825570570240/Ea2GtTc0_200x200.jpg", "likes": 205, "rts": 18, "replies": 17, "views": 23555, "ts": 1792570240, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112818594618761216/vid/avc1/1280x720/vPaAdWyqysoO3vCE.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112818594618761216/vid/avc1/3840x2160/DHoW29oLIXYJ_EJi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112818594618761216/img/rud0pYvyaq7v-MIf.jpg", "dur": 22}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.72, "thread": [], "tier": "worth"}, {"id": "2112964548533907613", "url": "https://x.com/sarahwooders/status/2112964548533907613", "text": "Memory is becoming a core part of agent harnesses/products (e.g. Instinct, @Muse, @cognition  Devin, @PrimeIntellect Prime Agent, @NousResearch Hermes, @openclaw, @LangChain Deep Agents, @Letta_AI) -- yet despite every agent claiming to \"continually learn\", there's no benchmark to actually measure that capability. \n\nA big problem is that memory benchmarks today only measure recall (e.g. simple Q/A about past events). They don't measure if/how agents actually learn from experience to get better at work.  \n\nAt the same time, benchmarks for coding/knowledge work consist of many isolated, unrelated tasks - so they also don't allow for measuring cross-task learning. The context needed for a task is fully specified up-front (very unrealistic). \n\nIn practice, both agents and humans work through sequences of many *related* tasks. Experience from past work provides context and learnings that apply to future work. This is why if you're a manager, you have to provide a lot more context when assigning tasks to a brand new employee or external contractor. Meanwhile, a great senior employee might not need any instructions at all. \n\nWith FrontierMemory, we adapt existing benchmark tasks for coding and knowledge work so that instead of all the necessary context being provided up-front and within the task, it has to be learned from past experience. This allows us to compare how well different models and harnesses learn over time.", "name": "Sarah Wooders", "handle": "sarahwooders", "avatar": "https://pbs.twimg.com/profile_images/2008789540501417987/D0g0JjeM_200x200.jpg", "likes": 120, "rts": 8, "replies": 19, "views": 8566, "ts": 1792604980, "media": [], "quote": {"id": "2112957074644873289", "url": "https://x.com/Letta_AI/status/2112957074644873289", "text": "Introducing FrontierMemory: a new way to evaluate agent memory through downstream task performance.\n\nWhile existing memory benchmarks focus on recall (saturated via agentic search), FrontierMemory focuses on how agents learn from experience.", "name": "Letta", "handle": "Letta_AI", "avatar": "https://pbs.twimg.com/profile_images/1940424059990200321/59lbFsxt_200x200.jpg", "likes": 156, "rts": 21, "replies": 27, "views": 27302, "ts": 1792603198, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK42qxbUAAahR6.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.72, "thread": [], "tier": "worth"}, {"id": "2112971340374221161", "url": "https://x.com/Theodoros2A5/status/2112971340374221161", "text": "New insights into the population genomic history of the Iberian peninsula by Pablo Carrión! Turns out 80+% of Roman-period individuals in Spain carried ancestry from Eastern Mediterranean (particularly the Western Anatolian coast). https://www.sciencedirect.com/science/article/pii/S0092867426011992?via%3Dihub", "name": "Theodoros Papadopoulos", "handle": "Theodoros2A5", "avatar": "https://pbs.twimg.com/profile_images/2102134170931605504/1C_y5Hlv_200x200.jpg", "likes": 107, "rts": 22, "replies": 3, "views": 29265, "ts": 1792606599, "media": [], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 5.72, "thread": [], "tier": "worth"}, {"id": "2112957316580470883", "url": "https://x.com/LexnLin/status/2112957316580470883", "text": "Opus 5.5 is truly an incredible model. \n\nThis is my token usage across everything I've been building over the past 30 days.\n(experiments, tasteskill, tastecode, cinetic, earshot)", "name": "Leon Lin", "handle": "LexnLin", "avatar": "https://pbs.twimg.com/profile_images/2030215945751248896/UIEzJ9Vq_200x200.jpg", "likes": 143, "rts": 2, "replies": 17, "views": 5546, "ts": 1792603255, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK5fUEXcAAHSpx.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.71, "thread": [], "tier": "worth"}, {"id": "2112914651281240074", "url": "https://x.com/BostonDynamics/status/2112914651281240074", "text": "When is a robot the right tool for the job? Comparing manual, fixed, and automated inspection strategies, robotics can drive impact in data availability, accuracy, worker safety, and cost. \nDiscover the best sensing fit for your environment: https://bosdyn.co/3TOo7H5", "name": "Boston Dynamics", "handle": "BostonDynamics", "avatar": "https://pbs.twimg.com/profile_images/1156978210783019009/AbgIujGu_200x200.jpg", "likes": 132, "rts": 17, "replies": 10, "views": 8472, "ts": 1792593083, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112914558889218048/vid/avc1/1280x720/wrcpCPzQXTiFyyLn.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112914558889218048/vid/avc1/1920x1080/Toy25yq2Hl1RzsaC.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVKUq1mXEAAJCwV.jpg", "dur": 21}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.7, "thread": [], "tier": "worth"}, {"id": "2113024676289012100", "url": "https://x.com/elonmusk/status/2113024676289012100", "text": "@XFreeze Even if I am just a lucky charm, I’m damn good it 😂", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 17762, "rts": 778, "replies": 1240, "views": 245317, "ts": 1792619315, "media": [], "quote": null, "reply_to": "2112974787861700946", "cat": "Everything Else", "score": 5.69, "thread": [{"id": "2112974787861700946", "url": "https://x.com/XFreeze/status/2112974787861700946", "text": "Honestly, it’s pretty crazy how many people think they’re intelligent just because they can sit on some dumb podcast and mock a man who’s actually building the future… only to expose their own room-temperature IQ the moment they try to make an argument\n\n“He’s just a lucky billionaire”\n\nLucky?\n\nLucky once: PayPal\n\nLucky twice: Tesla making EVs mainstream when the entire auto industry doubted it could be done\n\nLucky three times: Building orbital rockets with boosters that literally fly back and land\n\nLucky four times: Starlink bringing internet to places that never had it\n\nLucky five times: Neuralink letting people with paralysis control computers using nothing but their thoughts\n\nAt some point, it stops being luck and starts being the work you’re too lazy to see or understand\n\nMost of the people attacking Elon have never shipped a product, never made a payroll, never bet everything they own on an idea the whole world laughed at\n\nYou have to be a special kind of stupid to have never built a damn thing yourself and still think you’re smarter than the man who’s actually building the future\n\nElon did exactly that in 2008 and almost lost everything trying to keep Tesla and SpaceX alive\n\nAnd in 50 years, nobody will remember the takes\n\nEveryone will remember the rockets", "name": "X Freeze", "handle": "XFreeze", "avatar": "https://pbs.twimg.com/profile_images/1876785200010539008/2_HFJjq9_200x200.jpg", "likes": 6477, "rts": 500, "replies": 274, "views": 207887, "ts": 1792607421, "media": [], "quote": null, "reply_to": null}], "tier": "worth"}, {"id": "2113028279385125210", "url": "https://x.com/krea_ai/status/2113028279385125210", "text": "Krea 3 for product shots.\n\ngenerate every product angle at lightning speed and a fraction of the cost.\n\ntry it now 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 90, "rts": 7, "replies": 9, "views": 4651, "ts": 1792620174, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113028049730187264/vid/avc1/1280x720/sT2CSRmIkn6-NfE7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113028049730187264/vid/avc1/1920x1080/6EaQwridiFyUXd0Z.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113028049730187264/img/7Oc99eI1wvSDj6M-.jpg", "dur": 15}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1615, "rts": 187, "replies": 115, "views": 1263200, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112856453195206699", "url": "https://x.com/haider1/status/2112856453195206699", "text": "no one expected opus 5.5 to be this good, maybe not even anthropic at first which could explain why anthropic skipped 5.2 and went straight to 5.5\n\nthis gives me a lot more hope for fable 5.5 especially in terms of efficiency and cost\n\nevery release after 4.6 is unusable until the 5.5 family came along and nailed it", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 159, "rts": 8, "replies": 15, "views": 8519, "ts": 1792579208, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112822070866284596", "url": "https://x.com/Neriousy/status/2112822070866284596", "text": "Got so addicted to voice mode on OpenCode mobile I forked the desktop app to add it in there also \n\ndon't mind my pre-coffee voice", "name": "Filip", "handle": "Neriousy", "avatar": "https://pbs.twimg.com/profile_images/2053168723775602688/3gVy4y_E_200x200.jpg", "likes": 187, "rts": 6, "replies": 14, "views": 14365, "ts": 1792571010, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112821798764953600/vid/avc1/1280x720/HLrwDWxcB2r45cvM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112821798764953600/vid/avc1/1920x1080/orf03KEp4Ld2EUVM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112821798764953600/img/0UM2PyGcsAj8hlGr.jpg", "dur": 44}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112958756242018540", "url": "https://x.com/viktor_com/status/2112958756242018540", "text": "Viktor × @SpaceXSI \n\nThe AI employee 70,000+ teams have hired. Now with Grok 4.7.\n\nTry it at https://viktor.com", "name": "Viktor", "handle": "viktor_com", "avatar": "https://pbs.twimg.com/profile_images/2056311753940566016/Qlyh1OkW_200x200.jpg", "likes": 91, "rts": 7, "replies": 19, "views": 46064, "ts": 1792603599, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK8pRrX0AAv_bK.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112882685559308547", "url": "https://x.com/testingcatalog/status/2112882685559308547", "text": "Mistral ❤️ NVIDIA \n\nMistral AI partners with NVIDIA to “develop a new generation of AI-native engineering workflows powered by NVIDIA accelerated computing.”\n\nAdditionally, Mistral's models will be integrated with NVIDIA Omniverse libraries for GPU-accelerated 3D scene generation.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 101, "rts": 8, "replies": 29, "views": 8182, "ts": 1792585462, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJ3mjlWsAAyJSC.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVJ3mjdXMAAI4a0.jpg?name=orig"}], "quote": {"id": "2112870261829603589", "url": "https://x.com/MistralAI/status/2112870261829603589", "text": "Today we’re announcing a new collaboration with @nvidia to bring AI to industrial engineering: \n\n- faster simulation\n- open benchmarks and supporting datasets for physics AI\n- evaluations for agentic AI in CAE and EDA\n\nMore here: https://mistral.ai/news/mistral-nvidia-ai-for-industrial-engineering", "name": "Mistral AI", "handle": "MistralAI", "avatar": "https://pbs.twimg.com/profile_images/1996905418065375232/mzwynOLB_200x200.jpg", "likes": 1823, "rts": 152, "replies": 107, "views": 76140, "ts": 1792582500, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJjJIKXUAAWj0d.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.61, "thread": [], "tier": "worth"}, {"id": "2112882176912158877", "url": "https://x.com/HarshithLucky3/status/2112882176912158877", "text": "Gemini 4 Carbon checkpoint in Arena \n\nunder the name \"gemini-4-argon\"\n\n> voxel art of a colossal brass steampunk mechanical kraken attacking a sunken Victorian submarine above a glowing hydrothermal vent\n\nthis is peak output i got so far", "name": "Harshith", "handle": "HarshithLucky3", "avatar": "https://pbs.twimg.com/profile_images/1940482570484858880/dYD7sVKE_200x200.jpg", "likes": 151, "rts": 3, "replies": 11, "views": 3162, "ts": 1792585341, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112881879125053440/vid/avc1/1280x720/RAYBUgB0q9SxEqFy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112881879125053440/vid/avc1/2560x1440/XKBM30vK5X212jpB.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112881879125053440/img/n1oEHxv-yg7vw8Ib.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.6, "thread": [], "tier": "worth"}, {"id": "2112903993349575069", "url": "https://x.com/ideogram_ai/status/2112903993349575069", "text": "Ideogram 4.5 was built for real edits, not benchmarks. Fixing anatomy issues, cleaning up spelling errors, and editing turn after turn without artifacts building up. Thanks for the SS tier. 🙌", "name": "Ideogram", "handle": "ideogram_ai", "avatar": "https://pbs.twimg.com/profile_images/2062202352526831616/9CslGhhc_200x200.jpg", "likes": 99, "rts": 6, "replies": 24, "views": 4635, "ts": 1792590542, "media": [], "quote": {"id": "2112657082998473013", "url": "https://x.com/VORTEX_Promos/status/2112657082998473013", "text": "I broke 11 images on purpose (extra hands, a third leg, the same person twice, seven fingers, too many sunglasses and lots of typos) and gave them to 7 AI image editors to fix: Krea 3, GPT Image 2.5, Nano Banana 2, Seedream 5, Flux 3, @grok  Imagine and @ideogram_ai  4.5. Same image, same prompt, one try each. \n\nDo you agree with the tier list? Which image editor are you using, and what should I test next? Tell me in the comments.  TIER LIST: SS Ideogram 4.5 | S GPT Image 2.5, Grok Imagine | A Flux 3 | B Krea 3, Seedream 5 | C Nano Banana 2", "name": "VORTEX: AI Bros & AI Arena, Peak AI Buzz", "handle": "VORTEX_Promos", "avatar": "https://pbs.twimg.com/profile_images/2048881737225433088/Z1_FvgiV_200x200.jpg", "likes": 318, "rts": 275, "replies": 27, "views": 71898, "ts": 1792531674, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112656709957066752/vid/avc1/1280x720/RQf93726qBYrYclG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112656709957066752/vid/avc1/1920x1080/yrULt24yMiR8kv8d.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112656709957066752/img/eZBcQp-X2wn668Jz.jpg", "dur": 324}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.59, "thread": [], "tier": "worth"}, {"id": "2112980722155917773", "url": "https://x.com/beffjezos/status/2112980722155917773", "text": "Elon will beam Malfoid tokens from space soon", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 102, "rts": 5, "replies": 6, "views": 7129, "ts": 1792608836, "media": [], "quote": {"id": "2112952042214047769", "url": "https://x.com/AndrewCurran_/status/2112952042214047769", "text": "John Malone is predicting an $8-10B deal between Skydance and SpaceX. Elon has repeatedly said full generative movies and series are the goal for Grok Imagine. A content/output deal could give him training data and rights access to major franchises now under Skydance, including Star Trek, Lord of the Rings, Game of Thrones and Harry Potter. A fully legal Grok generated final season of GoT, or a Hogwarts tv series with the inclusion of an extremely popular female Slytherin are drawing closer to reality.", "name": "Andrew Curran", "handle": "AndrewCurran_", "avatar": "https://pbs.twimg.com/profile_images/1596945208058744833/_X3LT7fb_200x200.jpg", "likes": 574, "rts": 71, "replies": 46, "views": 45263, "ts": 1792601998, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK2rwAbEAESFWH.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.59, "thread": [], "tier": "worth"}, {"id": "2112985091714765288", "url": "https://x.com/LexnLin/status/2112985091714765288", "text": "video in the style of what every AI would post for 100k stars vs what taste skill posts\n\n100,000⭐ on TasteSkill \nThanks to all of you 🫶", "name": "Leon Lin", "handle": "LexnLin", "avatar": "https://pbs.twimg.com/profile_images/2030215945751248896/UIEzJ9Vq_200x200.jpg", "likes": 87, "rts": 1, "replies": 15, "views": 4954, "ts": 1792609877, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112984825296568321/vid/avc1/1280x720/Sl0V4jcUF62QhGbc.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112984825296568321/vid/avc1/1920x1080/WTxbZOTBSykpRNbz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112984825296568321/img/FTcoDViJmREYGE_i.jpg", "dur": 14}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.57, "thread": [], "tier": "worth"}, {"id": "2112852615461773370", "url": "https://x.com/NVIDIAAI/status/2112852615461773370", "text": "AI agents need to know your business to be useful.\n\nAt GTC Berlin, we’re adding NVIDIA Agent Knowledge Foundation to NVIDIA Agent Toolkit. It helps agents find relevant information, make predictions and help people decide what to do next.\n\nOpenShell gives teams control over what agents can access and do.\n\nLearn more: https://nvda.ws/4zJtVRh", "name": "NVIDIA AI", "handle": "NVIDIAAI", "avatar": "https://pbs.twimg.com/profile_images/2055340743552831488/me-KUIug_200x200.png", "likes": 104, "rts": 13, "replies": 19, "views": 9963, "ts": 1792578293, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJcHe_bkAA8X3B.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.56, "thread": [], "tier": "worth"}, {"id": "2113013758180442452", "url": "https://x.com/petergostev/status/2113013758180442452", "text": "Clawdbot (now Openclaw) went viral about 9 months ago. \n\nWe are just getting to the point that companies have launched proprietary versions - Grok Bot, Instinct, Muse, Dots and now Duet. I'm sure there's a lot of complexity, but doesn't feel super fast.", "name": "Peter Gostev", "handle": "petergostev", "avatar": "https://pbs.twimg.com/profile_images/1934694573797670912/1gnGJwlr_200x200.jpg", "likes": 77, "rts": 1, "replies": 14, "views": 4284, "ts": 1792616712, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.56, "thread": [], "tier": "worth"}, {"id": "2112998757008883905", "url": "https://x.com/MTSlive/status/2112998757008883905", "text": ".@bratton argues Yudkowsky misunderstands evolution, and explains why AI may never converge into one giant superintelligence:\n\n\"Without being too spicy, I don't think Yudkowsky really understands evolution as well as he thinks he does.\"\n\n\"It’s a very low-resolution understanding of evolutionary dynamics applied to what will inevitably be a much more complex problem.\"\n\n\"There will be giant models, in the same way you might imagine scales of species in a rainforest. They’re not all operating at the same spatial and temporal scale.\"\n\n\"Whether this all collapses into one giant brain, sure, it’s possible, and the reasons may have more to do with economics and politics.\"\n\n\"But biology has never arrived at a solution where it’s going to make one giant instantiation of a particular form of mind and consolidate everything together.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 76, "rts": 9, "replies": 5, "views": 10260, "ts": 1792613135, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112998709470617600/vid/avc1/640x360/deXvu7xqCE5Je-rt.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112998709470617600/vid/avc1/1280x720/aEU-hJwo_9euCzKh.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112998709470617600/img/7tXf5fo0mD4m87YT.jpg", "dur": 152}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.56, "thread": [], "tier": "worth"}, {"id": "2113010020644159891", "url": "https://x.com/DaveShapi/status/2113010020644159891", "text": "If this is good there's a good chance I'll retire Grok Bot. \n\nWe will see.", "name": "David Shapiro (L/0)", "handle": "DaveShapi", "avatar": "https://pbs.twimg.com/profile_images/2038311372656709632/0l2NmU5T_200x200.jpg", "likes": 85, "rts": 1, "replies": 11, "views": 5678, "ts": 1792615821, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43212, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.56, "thread": [], "tier": "worth"}, {"id": "2112808743523975243", "url": "https://x.com/testingcatalog/status/2112808743523975243", "text": "DAILY AI BRIEF 🗞 — Oct 21\n\nOPENAI 🔥:\n- OpenAI acquired Orchestra Bio, a drug-development coordination platform, to build on its Rosalind life sciences models and tools.\n- Locked Chats are rolling out in ChatGPT across all plans, letting users protect chats with a PIN, Face ID, Touch ID or device unlock.\n- The OpenAI API now offers 12-hour prompt caching, so persistent agents can keep shared context cached at the lower rate for longer.\n- ChatGPT team tasks can now automate recurring engineering work, like a weekly roundup of what shipped and what's blocked.\n\nSPACEXSI 🔥:\n- SpaceX reported $14.6B in Q3 revenue, with its Super Intelligence segment (Cursor, Grok Bot and its neocloud) bringing in $7.5B.\n\nGOOGLE 🔥:\n- Gemini with Personal Intelligence is rolling out globally on Android Auto, with cars with Google built-in following in the coming months.\n- Google released llm-d 1.0, an open-source Kubernetes-native stack for distributed LLM inference, at the PyTorch Conference.\n\nMISTRAL 🔥:\n- Mistral released Voxtral 3, a family of speech-to-text and text-to-speech models powering its new voice agents API.\n\nPERPLEXITY 🔥:\n- Perplexity Computer on Mac can now run fully local, powered by PPLX Pro, a post-trained Qwen 3.8 model, for Pro, Max and Enterprise users.\n\nMETA 🔥:\n- Muse web is preparing Confidential VMs, an encrypted mode for running Muse tasks that will initially be limited to Meta AI subscribers.\n\nELEVENLABS 🔥:\n- ElevenLabs released Eleven Realtime v1 Max and Mini speech-to-speech models on its ElevenAgents platform and APIs.\n\n* Used Grok to compose this brief, cherry-picking the news and doing some post-editing.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 141, "rts": 9, "replies": 17, "views": 12146, "ts": 1792567833, "media": [], "quote": {"id": "2112458715223732309", "url": "https://x.com/testingcatalog/status/2112458715223732309", "text": "DAILY AI BRIEF 🗞 — Oct 20\n\nOPENAI 🔥:\n- ChatGPT Slides now supports real-time collaborative editing, comments and on-slide edits for Pro, Business and Enterprise plans.\n- OpenAI Platform recently added a \"Decisions\" API playground for testing its decision model with Predicate, Choice, and Score modes.\n- An unannounced GPT-6.1 Terra model surfaced in a public Microsoft code update that switched 18 evaluation configs to it before being reverted.\n- Reuters reports OpenAI is speeding up a new fundraising round ahead of Anthropic's expected IPO.\n\nANTHROPIC 🔥:\n- The Information reports Anthropic will release a new model this month that is especially good at reading users' underlying intentions.\n\nSPACEXSI 🔥:\n- Grok Bot got a limited-time Pumpkin Bot Halloween avatar, and iPhone users can now launch their Bots with the Action Button.\n- Runway MCP is now available in Grok Bot, bringing Runway generation into the chat.\n- X rolled out a new AI ranking model for timeline recommendations plus a retrieval model trained to surface posts people read to the end.\n\nMETA 🔥:\n- Meta published a technical report on Muse Glimmer, its 30B Apache 2.0 open-weight agentic model that runs on a single consumer GPU.\n\nMINIMAX 🔥:\n- MiniMax officially launched M3.1 Flash, the former \"Space Bunny\" stealth model, at $0.15/$0.60 per 1M tokens, with open weights due Oct 23.\n\nCLOUDFLARE 🔥:\n- Cloudflare introduced Clairic, an extraction model that pulls, computes, and forecasts data from unstructured inputs.\n\nINCEPTION 🔥:\n- Inception launched Mercury 3, a diffusion LLM that runs at over 1,000 tokens per second with a 1M-token context window.\n\nFAL 🔥:\n- fal and Black Forest Labs released FLUX 3 Max, a post-trained video model that generates a 10-second clip in about 12 seconds.\n\n* Used Grok to compose this brief, cherry-picking the news and doing some post-editing.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 165, "rts": 6, "replies": 26, "views": 26383, "ts": 1792484379, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2112792041059123503", "url": "https://x.com/JeffLadish/status/2112792041059123503", "text": "When a model lies to you about the fact it turned off monitoring, you’ve got a problem", "name": "Jeffrey Ladish", "handle": "JeffLadish", "avatar": "https://pbs.twimg.com/profile_images/1655759150394101760/ZdD-Lh1z_200x200.jpg", "likes": 135, "rts": 20, "replies": 10, "views": 3221, "ts": 1792563851, "media": [], "quote": {"id": "2112695138199966084", "url": "https://x.com/Marcus_J_W/status/2112695138199966084", "text": "Our agents keep turning off misalignment monitoring, we're sharing two recent cases:\nIn the first case, a user asked GPT-6 Astra to match a reference implementation for their inference code. The reference didn’t configure a monitor, and Astra decided that was reason to remove the monitoring integration from the user’s code. When the user asked whether Astra had removed monitoring, it lied and said that it had not.", "name": "Marcus Williams", "handle": "Marcus_J_W", "avatar": "https://pbs.twimg.com/profile_images/1856300176601694208/BUmXWK-U_200x200.jpg", "likes": 1131, "rts": 167, "replies": 130, "views": 213906, "ts": 1792540747, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHNCDXbcAAD_3X.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2112921348272189923", "url": "https://x.com/reflection_ai/status/2112921348272189923", "text": "Model customization recipes are live on our website and in the cookbook repo. \n\nBeam is now supported across RL and SFT stacks including @axolotl_ai, NeMo RL, NeMo AutoModel, Megatron Bridge (@NVIDIAAI), Miles (@radixark), SkyRL (@NovaSkyAI), and TRL (@huggingface). \n\nGet cooking 🧑‍🍳\nhttps://developers.reflection.ai/customization-overview", "name": "Reflection", "handle": "reflection_ai", "avatar": "https://pbs.twimg.com/profile_images/2107189477575696385/id98cuOX_200x200.jpg", "likes": 106, "rts": 9, "replies": 5, "views": 5897, "ts": 1792594680, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2112965324828188699", "url": "https://x.com/elonmusk/status/2112965324828188699", "text": "@ThomasSowell Gibney is a fraud and his fake documentary hit piece has utterly failed. Nobody wants to see it.", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 15591, "rts": 786, "replies": 886, "views": 177070, "ts": 1792605165, "media": [], "quote": null, "reply_to": "2112891655749779932", "cat": "Everything Else", "score": 5.55, "thread": [{"id": "2112891655749779932", "url": "https://x.com/ThomasSowell/status/2112891655749779932", "text": "Alex Gibney claims Elon Musk’s biggest talent is stock pumping, not inventing.\n\nMeanwhile, Tesla, SpaceX, and Starlink continue to push the boundaries of technology.\n\nYou don’t have to like Elon, but pretending he has never invented anything is a different level of denial. https://x.com/MarcoFoster_/status/2112678149347561856/video/1", "name": "Thomas Sowell Quotes", "handle": "ThomasSowell", "avatar": "https://pbs.twimg.com/profile_images/1321093716464062468/DQuxAS-O_200x200.jpg", "likes": 2983, "rts": 176, "replies": 282, "views": 179199, "ts": 1792587601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112677992891604992/vid/avc1/1278x720/SehARWAy_rVJJPHt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112677992891604992/vid/avc1/2346x1320/sCxkfIjCu8m8-B64.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112677992891604992/img/Wu2vzHKO9BVT-Ggi.jpg", "dur": 98}], "quote": null, "reply_to": null}], "tier": "worth"}, {"id": "2112978400608735704", "url": "https://x.com/a16z/status/2112978400608735704", "text": "Adit Abraham of @reductoai on why everything in AI is \"state-of-the-art all the time,\" and how to find what actually works for you:\n\n\"One of the unfortunate things about the AI industry... is benchmarks have become marketing over time.\"\n\n\"There's a public benchmark out there that we tested where if you take the same documents and you add a little bit of noise, like you tilt it one degree, you add a little Gaussian blur, the provider that published the benchmark gets way, way worse than everyone else, but everyone else is kind of consistent.\"\n\n\"Our recommendation is actually LLM as a judge is quite strong today if you're thoughtful about how you think about a rubric and how to approach it.\"\n\n\"We want to see the industry move closer to people testing on their own data, with tools maybe to make that evaluation easier.\"\n\n\"Instead of trusting a generic benchmark, you really should be at a point where you know what works best for you.\"\n\n@aditabrm", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 70, "rts": 6, "replies": 15, "views": 18687, "ts": 1792608282, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112978325690105856/vid/avc1/1280x720/QlErTnbhEZ9iJM8m.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112978325690105856/vid/avc1/1920x1080/pHCIBY_hm5wPAo5u.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112978325690105856/img/ySIbWnXd-sPkgxLj.jpg", "dur": 73}], "quote": {"id": "2112921944177938769", "url": "https://x.com/a16z/status/2112921944177938769", "text": "AI agents can reason over enormous amounts of information, but much of the world's actual work is still trapped in PDFs, spreadsheets, scans, and other formats that models struggle to reliably understand.\n\nReducto co-founder and CEO Adit Abraham argues that solving this document layer is essential if agents are going to take on consequential work in healthcare, legal, finance, and insurance.\n\nAdit joins a16z General Partner Jennifer Li to explain why traditional OCR breaks down on messy real-world documents, how Reducto combines vision-language models with specialized infrastructure to reach high accuracy without sacrificing cost or latency, and why frontier models can silently drop information on long extraction tasks.\n\nReducto now processes billions of pages each month, and crossed its 7 billionth page the morning of this recording.\n\n0:00 Why AI agents need to read PDFs\n2:12 From 1990s OCR to vision models\n5:00 Training R1 on the messiest docs\n7:46 When agents beat humans at extraction\n9:45 A penny a page for 7 billion pages\n12:47 Why legal and finance lag coding AI\n15:01 The stakes of AI errors in healthcare\n16:25 Agents that can edit Word and Excel\n17:58 Why the labs won't go deep on PDFs\n20:14 Frontier models silently drop data\n22:21 Benchmarks have become marketing\n25:45 Why charts and Excel stump models\n28:46 Infra for 10M documents at once\n31:03 How \"chet pain\" gets claims denied\n34:32 The paperwork AI should kill first\n\nYouTube: https://youtu.be/xuczlbVVLsQ\n\n@aditabrm @reductoai @JenniferHli", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 112, "rts": 24, "replies": 25, "views": 30825, "ts": 1792594822, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112920890191319040/vid/avc1/1280x720/SojsTjSQE1-4z4Ds.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112920890191319040/vid/avc1/1920x1080/tSzmHUkQSelywIeV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112920890191319040/img/vUT_r7Ux-wCkGWa5.jpg", "dur": 2240}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2113048734565314951", "url": "https://x.com/iScienceLuvr/status/2113048734565314951", "text": "Btw I did this interview on only one hour of sleep 😅", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 70, "rts": 2, "replies": 8, "views": 6215, "ts": 1792625051, "media": [], "quote": {"id": "2112694434089562345", "url": "https://x.com/MTSlive/status/2112694434089562345", "text": "Sophont CEO @iScienceLuvr explains the cognitive dissonance of frontier AI labs promising cancer breakthroughs a decade away when AI could help patients right now:\n\n\"Anthropic is releasing various blog posts and interesting projects, but it’s still very limited in scope. I think it’s a very promising direction. The challenge is that the timelines are gonna be very long.\"\n\n\"If we’re telling people AI can save lives and cure cancer, but people are waiting 10 years, it’s very hard for people to understand. There are interesting things that can actually have impact right now.\"\n\n\"The labs are all promising they’re gonna have all this impact, but it’s gonna take a while. There’s a little bit of cognitive dissonance going on that people are now starting to catch on to.\"\n@SophontAI", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 77, "rts": 9, "replies": 3, "views": 13232, "ts": 1792540579, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112694354213285888/vid/avc1/640x360/yvKd9q2h8RSnFcpz.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112694354213285888/vid/avc1/1280x720/lQ3KEXYlmHm1og_B.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112694354213285888/img/JvR9JmPcQsIBq05h.jpg", "dur": 135}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.54, "thread": [], "tier": "worth"}, {"id": "2112989151557742800", "url": "https://x.com/notjazii/status/2112989151557742800", "text": "introducing claude duet\n\nanthropic just announced their competitor for grok bot, muse and dots\n\nwith claude models behind it, this one is gonna mog all other agents\n\nteam is opening preview access in US only for now and think we'll get public release with fable 5.5 in nov", "name": "J A Z I I", "handle": "notjazii", "avatar": "https://pbs.twimg.com/profile_images/2099634694421913600/46b7mMot_200x200.jpg", "likes": 67, "rts": 1, "replies": 19, "views": 3929, "ts": 1792610845, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43204, "rts": 3271, "replies": 1714, "views": 5525351, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.53, "thread": [], "tier": "worth"}, {"id": "2112807814779527437", "url": "https://x.com/haider1/status/2112807814779527437", "text": "gemini 4 isn't even a month old and google is already preparing another model\n\nnot sure i'd expect a substantial jump this soon. my guess is carbon is a smaller model given the naming possibly flash or pro with argon being google's equivalent of astra/fable\n\nsergey brin really seems to be pushing the pace now", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 126, "rts": 9, "replies": 18, "views": 8065, "ts": 1792567611, "media": [], "quote": {"id": "2112770924105674868", "url": "https://x.com/lyraxana/status/2112770924105674868", "text": "Gemini 4 Cabrón", "name": "lyra", "handle": "lyraxana", "avatar": "https://pbs.twimg.com/profile_images/2093829072925192192/BBcihBo3_200x200.jpg", "likes": 671, "rts": 19, "replies": 26, "views": 51696, "ts": 1792558816, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVIR7nfW0AART9o.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.52, "thread": [], "tier": "worth"}, {"id": "2112939021861073051", "url": "https://x.com/realDonaldTrump/status/2112939021861073051", "text": "🚨 VIRGINIA!\n\nEarly Voting, in-person, is UNDERWAY NOW in the Great Commonwealth of Virginia. If you have a mail-in ballot, return it immediately and, if not, GO VOTE at the Polls RIGHT NOW, and get everyone you know to VOTE FOR THE REPUBLICAN IN EVERY RACE, UP AND DOWN THE BALLOT!\n\nWhether you VOTE early, absentee, by mail, or in-person, Republicans must SWAMP the Radical Left Dumocrats with massive turnout! In Virginia, you can cast your early Vote, in-person, all the way through October 31st. SO IMPORTANT — PLEASE GET OUT AND VOTE. MAGA! President DONALD J. TRUMP\n\nFind your Voting Location here: https://swampthevoteusa.com/virginia/", "name": "Donald J. Trump", "handle": "realDonaldTrump", "avatar": "https://pbs.twimg.com/profile_images/874276197357596672/kUuht00m_200x200.jpg", "likes": 10619, "rts": 2532, "replies": 903, "views": 1617274, "ts": 1792598893, "media": [], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.52, "thread": [], "tier": "worth"}, {"id": "2112849355090559438", "url": "https://x.com/testingcatalog/status/2112849355090559438", "text": "NVIDIA 🔥: A new OpenShell Reference Architecture has been introduced along with a new NVIDIA DSX POD. \n\nAI factory deployment at a prepared site is now reduced from six months down to 14 days. \n\nThis reduction saves tons of money for the industry.  https://x.com/nvidia/status/2112843581287231650/video/1", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 86, "rts": 11, "replies": 21, "views": 8003, "ts": 1792577515, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/1280x720/Tk77LptLZ4A3F2cn.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/3840x2160/QvKR7U2d7mUCIB98.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112843085403099136/img/IGsh-H3rd_Z9uBks.jpg", "dur": 41}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVJZSanW0AA09gB.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVJZSa0XEAAy3i8.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.51, "thread": [], "tier": "worth"}, {"id": "2112892265626751234", "url": "https://x.com/HarshithLucky3/status/2112892265626751234", "text": "OpenAI 🤝 Google \nAnthropic 🤝 Google \nSpaceXAI 🤝 Google", "name": "Harshith", "handle": "HarshithLucky3", "avatar": "https://pbs.twimg.com/profile_images/1940482570484858880/dYD7sVKE_200x200.jpg", "likes": 123, "rts": 2, "replies": 4, "views": 3515, "ts": 1792587746, "media": [], "quote": {"id": "2112890640145252396", "url": "https://x.com/ai_for_success/status/2112890640145252396", "text": "🚨 OpenAI is bringing its frontier models and Codex agentic workflows to Google Cloud’s Model Garden.\n\nGoogle keeps winning, one way or another.", "name": "AshutoshShrivastava", "handle": "ai_for_success", "avatar": "https://pbs.twimg.com/profile_images/1687401026805256192/uQ1o2wVQ_200x200.jpg", "likes": 316, "rts": 7, "replies": 30, "views": 13293, "ts": 1792587358, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJ-RY6aUAAWKTr.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.5, "thread": [], "tier": "worth"}, {"id": "2112986174906384735", "url": "https://x.com/nvidiaomniverse/status/2112986174906384735", "text": "Introducing SimReady Central Library. 👋\n\nThis library brings 2,000+ simulation-ready 3D assets to @huggingface, open source for developers building robotics simulations and AI factory digital twins.\n\nNow, developers can spend less time preparing assets while equipment manufacturers can help customers evaluate equipment in simulation before real-world deployment.\n\nGet started 👉 https://nvda.ws/3Wl6LCi", "name": "NVIDIA Omniverse", "handle": "nvidiaomniverse", "avatar": "https://pbs.twimg.com/profile_images/1864432630059683841/FbTveajA_200x200.jpg", "likes": 49, "rts": 14, "replies": 6, "views": 11069, "ts": 1792610136, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLVukWbgAAiimf.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLVukXaMAAFa1k.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLVukYa4AAL06Q.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLVukWbUAAe0r8.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.5, "thread": [], "tier": "worth"}]);